const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => crypto.randomUUID();
const names=['Los Cóndores','Atlético Norte','Deportivo Sur','Real Maipú','Unión Central','Barrio FC','Los Leones','Sporting Andes'];
const colors=['#b44a38','#3f6fb3','#d2a942','#7555aa','#40947c','#d07a39','#9c5268','#548eaa'];
const seedTeams=names.map((name,i)=>({id:`t${i}`,name,short_name:['CON','ATN','SUR','RMA','UNC','BFC','LEO','AND'][i],color:colors[i],captain_id:null}));
const seedPlayers=seedTeams.flatMap((t,i)=>Array.from({length:15},(_,j)=>({id:`p${i}-${j}`,team_id:t.id,name:['Matías','Benjamín','Vicente','Tomás','Diego','Lucas','Nicolás','Joaquín','Felipe','Gabriel','Martín','Cristóbal','Sebastián','Ignacio','Alonso'][j]+' '+['Rojas','Muñoz','Soto','Vargas','Díaz','Pérez','Torres','Silva'][(i+j)%8],number:j+1,position:j===0?'POR':j<5?'DEF':j<9?'MED':'DEL'})));
const seedMatches=[{id:'m0',home_id:'t0',away_id:'t1',home_score:2,away_score:1,status:'live',minute:67,round:4,kickoff:'2026-10-30T22:00:00Z',venue:'Cancha Municipal · Santiago'},...Array.from({length:12},(_,i)=>({id:`m${i+1}`,home_id:`t${(i*2+2)%8}`,away_id:`t${(i*2+3)%8}`,home_score:i<8?(i+2)%4:0,away_score:i<8?i%3:0,status:i<8?'finished':'scheduled',minute:0,round:i<8?Math.floor(i/4)+1:4,kickoff:`2026-${i<8?'10-24':'11-01'}T${18+i%4}:00:00Z`,venue:'Complejo Deportivo Benjaix'}))];
const initial={teams:seedTeams,players:seedPlayers,matches:seedMatches,events:[{id:'e1',match_id:'m0',team_id:'t0',player_id:'p0-9',minute:23,type:'goal'},{id:'e2',match_id:'m0',team_id:'t1',player_id:'p1-10',minute:41,type:'goal'},{id:'e3',match_id:'m0',team_id:'t0',player_id:'p0-9',minute:61,type:'goal'}],lineups:[]};
let data=structuredClone(initial), db=null, profile=null, demo=true, filter='all', search='', selectedTeam='', loadVersion=0;
let demoProfile=null;
try{const saved=JSON.parse(localStorage.getItem('benjaix-demo-v1'));if(saved?.teams&&saved?.matches&&saved?.players&&saved?.events&&saved?.lineups)data=saved;}catch{}
const team=id=>data.teams.find(t=>t.id===id)||{name:'Equipo eliminado',short_name:'?',color:'#667766'};
const player=id=>data.players.find(p=>p.id===id);
const crest=(t,mini=false)=>`<span class="crest ${mini?'table-crest':''}" style="--team-color:${/^#[0-9a-f]{6}$/i.test(t.color)?t.color:'#667766'}">${esc(t.short_name)}</span>`;
const date=v=>new Intl.DateTimeFormat('es-CL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Santiago'}).format(new Date(v));
const statusText={live:'EN VIVO',finished:'FINALIZADO',scheduled:'PROGRAMADO'};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function standings(){const rows=data.teams.map(t=>({...t,pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0}));for(const m of data.matches.filter(m=>m.status==='finished')){const h=rows.find(t=>t.id===m.home_id),a=rows.find(t=>t.id===m.away_id);if(!h||!a)continue;h.pj++;a.pj++;h.gf+=m.home_score;h.gc+=m.away_score;a.gf+=m.away_score;a.gc+=m.home_score;if(m.home_score===m.away_score){h.pe++;a.pe++;h.pts++;a.pts++;}else{const w=m.home_score>m.away_score?h:a,l=w===h?a:h;w.pg++;w.pts+=3;l.pp++;}}return rows.sort((a,b)=>b.pts-a.pts||(b.gf-b.gc)-(a.gf-a.gc)||b.gf-a.gf||a.name.localeCompare(b.name));}
function table(compact=false){return `<div class="panel table-wrap"><table><thead><tr><th>#</th><th>EQUIPO</th><th>PJ</th>${compact?'':'<th>PG</th><th>PE</th><th>PP</th><th>GF</th><th>GC</th>'}<th>DG</th><th>PTS</th></tr></thead><tbody>${standings().map((t,i)=>`<tr><td class="${i<4?'rank':''}">${i+1}</td><td><a href="#equipos" data-team="${t.id}">${crest(t,true)}${esc(t.name)}</a></td><td>${t.pj}</td>${compact?'':`<td>${t.pg}</td><td>${t.pe}</td><td>${t.pp}</td><td>${t.gf}</td><td>${t.gc}</td>`}<td>${t.gf-t.gc>0?'+':''}${t.gf-t.gc}</td><td>${t.pts}</td></tr>`).join('')}</tbody></table><div class="table-note">Los primeros 4 clasifican a playoffs · Solo partidos finalizados</div></div>`;}
function matchCard(m){return `<article class="match-card ${m.status==='live'?'live':''}" tabindex="0" role="button" data-match="${m.id}" aria-label="Ver ${esc(team(m.home_id).name)} contra ${esc(team(m.away_id).name)}"><div class="match-meta"><span>${m.status==='live'?'<span class="live-label"><i class="live-dot"></i>EN VIVO</span>':statusText[m.status]}</span><span>JORNADA ${m.round}</span></div><div class="match-teams"><div class="team">${crest(team(m.home_id))}${esc(team(m.home_id).name)}</div><div class="score">${m.status==='scheduled'?'VS':`${m.home_score} : ${m.away_score}`}<small>${m.status==='live'?m.minute+"′ · En juego":m.status==='finished'?'Tiempo completo':date(m.kickoff)}</small></div><div class="team">${crest(team(m.away_id))}${esc(team(m.away_id).name)}</div></div><div class="match-footer"><span>⌖ ${esc(m.venue)}</span><span>Ver partido ↗</span></div></article>`;}
const heading=(title,sub)=>`<div class="page-heading"><div><span class="eyebrow">BENJAIX CUP / TEMPORADA 2026</span><h1>${title}</h1><p>${sub}</p></div><span class="tag">◈ Liga de fútbol · 2026</span></div>`;
function home(){const live=data.matches.filter(m=>m.status==='live'),next=data.matches.filter(m=>m.status==='scheduled').sort((a,b)=>a.kickoff.localeCompare(b.kickoff));return heading('La liga se vive aquí.','Cada partido cuenta. Sigue el camino hacia la copa.')+`<section class="hero"><div class="hero-text"><span class="eyebrow">UNA LIGA. UNA PASIÓN. UNA COPA.</span><h2>El barrio juega.<br><em>La historia se escribe.</em></h2><p>Resultados, protagonistas y toda la emoción de Benjaix Cup. Vive cada jornada con tu equipo.</p><a href="#partidos" class="button">Explorar partidos <span>↗</span></a></div><div class="hero-art" aria-hidden="true"></div></section><div class="metrics">${[[data.teams.length,'Equipos en competencia','♧'],[data.matches.filter(m=>m.status==='finished').length,'Partidos disputados','⚽'],[data.matches.reduce((s,m)=>s+(m.status==='scheduled'?0:m.home_score+m.away_score),0),'Goles celebrados','◎'],[data.players.length,'Jugadores inscritos','♙']].map(([n,l,i])=>`<div class="metric"><div><small>${l}</small><strong>${n}</strong></div><i>${i}</i></div>`).join('')}</div><div class="columns"><section><div class="section-title"><h2><span class="live-dot"></span> El balón está en juego</h2><a href="#partidos" class="text-link">Todos los partidos ↗</a></div>${live.map(matchCard).join('')||'<div class="panel empty">No hay partidos en vivo en este momento.</div>'}<div class="section-title" style="margin-top:25px"><h2>Próximos encuentros</h2><span class="tiny">NO TE LOS PIERDAS</span></div>${next.slice(0,2).map(matchCard).join('')||'<div class="empty">Próximamente se publicará el calendario.</div>'}</section><section><div class="section-title"><h2>La carrera por la copa</h2><a href="#tabla" class="text-link">Ver tabla ↗</a></div>${table(true)}<div class="spotlight"><span class="eyebrow">DENTRO DE LA CANCHA</span><h3>Los nombres detrás del escudo.</h3><p>Conoce los planteles y las alineaciones que dan vida a nuestra liga.</p><a href="#equipos" class="text-link">Explorar equipos ↗</a></div></section></div>`;}
function matches(){return heading('Partidos','El calendario, los resultados y el minuto a minuto de la liga.')+`<div class="toolbar"><div class="filters">${[['all','Todos'],['live','● En vivo'],['scheduled','Próximos'],['finished','Finalizados']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'selected':''}">${l}</button>`).join('')}</div><input id="search" type="search" placeholder="Buscar equipo…" value="${esc(search)}" aria-label="Buscar equipo"></div><div class="grid" id="match-list">${filteredMatches()}</div>`;}
function filteredMatches(){return data.matches.filter(m=>(filter==='all'||m.status===filter)&&`${team(m.home_id).name} ${team(m.away_id).name}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.kickoff.localeCompare(a.kickoff)).map(matchCard).join('')||'<div class="empty">No hay partidos con estos filtros.</div>';}
function teamsView(){return heading('Equipos','Distintos escudos. La misma pasión.')+`<div class="grid">${data.teams.map(t=>`<article class="team-card" tabindex="0" role="button" data-team="${t.id}">${crest(t)}<h3>${esc(t.name)}</h3><p>${data.players.filter(p=>p.team_id===t.id).length} jugadores inscritos</p><span class="text-link">Ver plantel ↗</span></article>`).join('')||'<div class="empty">Aún no hay equipos inscritos.</div>'}</div>`;}
function stats(){const goals={};for(const e of data.events.filter(e=>e.type==='goal'&&player(e.player_id)))goals[e.player_id]=(goals[e.player_id]||0)+1;return heading('Estadísticas','Los protagonistas de Benjaix Cup.')+`<div class="notice">Las estadísticas individuales se calculan desde los eventos registrados por el administrador.</div><section class="panel"><div class="rule"><h3>Goleadores</h3></div><table><thead><tr><th>#</th><th>JUGADOR</th><th>EQUIPO</th><th>GOLES</th></tr></thead><tbody>${Object.entries(goals).sort((a,b)=>b[1]-a[1]).map(([id,g],i)=>`<tr><td>${i+1}</td><td>${esc(player(id).name)}</td><td>${esc(team(player(id).team_id).name)}</td><td class="green">${g}</td></tr>`).join('')}</tbody></table>${Object.keys(goals).length?'':'<div class="empty">Todavía no hay goles registrados.</div>'}</section>`;}
const options=(list,valueKey='id',labelKey='name',selected='')=>list.map(x=>`<option value="${esc(x[valueKey])}" ${x[valueKey]===selected?'selected':''}>${esc(x[labelKey])}</option>`).join('');
function login(){return heading('Acceso al panel','Gestiona la competencia o acompaña a tu equipo.')+`<div class="panel form-panel"><span class="eyebrow">ÁREA DE GESTIÓN</span><h2>Bienvenido a la cancha.</h2><p class="muted">Ingresa con la cuenta que te asignó la organización.</p><form id="login" class="form-grid"><label>Correo electrónico<input name="email" type="email" required autocomplete="username" placeholder="tu@correo.cl"></label><label>Contraseña<input name="password" type="password" required minlength="6" autocomplete="current-password"></label><button ${demo?'disabled':''}>Ingresar al panel ↗</button></form>${demo?'<div class="notice" style="margin-top:20px">Modo demostración: los cambios se guardan solo en este navegador.</div><div class="toolbar"><button data-demo="admin">Probar administrador</button><button class="outline" data-demo="captain">Probar capitán</button></div>':''}</div>`;}
function panel(){const p=demo?demoProfile:profile;if(!p)return login();const admin=p.role==='admin',owned=admin?data.teams:data.teams.filter(t=>t.captain_id===p.id);if(!owned.some(t=>t.id===selectedTeam))selectedTeam=owned[0]?.id||'';const t=team(selectedTeam),players=data.players.filter(x=>x.team_id===selectedTeam);return heading(admin?'Centro de control':'Mi equipo',admin?'Administra los equipos, el calendario y los resultados.':'Tu plantel y tus alineaciones, en un solo lugar.')+`<div class="toolbar"><span class="tag">${admin?'ADMINISTRADOR':'CAPITÁN'}${demo?' · DEMO LOCAL':''}</span><button id="logout" class="outline">Cerrar sesión</button></div>${demo?'<div class="notice">Entorno de demostración. Los cambios no afectan al campeonato real.</div>':''}${admin?`<div class="admin-grid"><section class="panel"><h3>Nuevo equipo</h3><form id="team-form" class="form-grid"><label>Nombre<input name="name" required maxlength="60"></label><label>Abreviatura<input name="short_name" required maxlength="3"></label><label>Color<input name="color" type="color" value="#699b44"></label><button>Crear equipo</button></form></section><section class="panel"><h3>Programar partido</h3><form id="match-form" class="form-grid"><label>Local<select name="home_id">${options(data.teams)}</select></label><label>Visitante<select name="away_id">${options(data.teams,'id','name',data.teams[1]?.id)}</select></label><label>Fecha y hora (hora de tu dispositivo)<input name="kickoff" type="datetime-local" required></label><label>Cancha<input name="venue" required maxlength="100"></label><label>Jornada<input name="round" type="number" min="1" max="100" value="1" required></label><button>Programar partido</button></form></section></div><section class="panel rule" style="margin:22px 0"><h3>Marcadores y eventos</h3><label>Seleccionar partido<select id="manage-match"><option value="">Selecciona un partido</option>${data.matches.map(m=>`<option value="${m.id}">${esc(team(m.home_id).name)} vs ${esc(team(m.away_id).name)} · J${m.round}</option>`).join('')}</select></label><div id="score-editor"></div></section>`:''}<section class="panel rule" style="margin-top:22px"><div class="section-title"><h2>Gestión del plantel</h2></div>${owned.length?`<label>Equipo<select id="owned-team">${options(owned,'id','name',selectedTeam)}</select></label><div class="admin-grid" style="margin-top:22px"><div><form id="edit-team" class="form-grid"><label>Nombre del equipo<input name="name" value="${esc(t.name)}" required maxlength="60"></label><label>Abreviatura<input name="short_name" value="${esc(t.short_name)}" required maxlength="3"></label><label>Color<input name="color" type="color" value="${esc(t.color)}"></label>${admin?`<label>UUID de la cuenta del capitán<input name="captain_id" value="${esc(t.captain_id||'')}" placeholder="UUID desde Authentication → Users"></label>`:''}<button>Guardar equipo</button></form><h3 style="margin-top:28px">Agregar jugador</h3><form id="player-form" class="form-grid"><label>Nombre completo<input name="name" required maxlength="80"></label><label>Dorsal<input type="number" min="1" max="99" name="number" required></label><label>Posición<select name="position"><option>POR</option><option>DEF</option><option>MED</option><option>DEL</option></select></label><button>Inscribir jugador</button></form></div><div><h3>Plantel · ${players.length} jugadores</h3>${players.map(p=>`<div class="roster-row"><span><b class="green">${p.number}</b> ${esc(p.name)} <small>${p.position}</small></span><button data-delete-player="${p.id}">Quitar</button></div>`).join('')||'<p class="muted">Agrega tu primer jugador.</p>'}</div></div><h3 style="margin-top:30px">Alineación por partido</h3><label>Partido<select id="lineup-match"><option value="">Selecciona un encuentro</option>${data.matches.filter(m=>m.home_id===selectedTeam||m.away_id===selectedTeam).map(m=>`<option value="${m.id}">${esc(team(m.home_id).name)} vs ${esc(team(m.away_id).name)} · ${statusText[m.status]}</option>`).join('')}</select></label><div id="lineup-editor"></div>`:'<div class="empty">Todavía no tienes un equipo asignado. La organización debe vincular tu cuenta.</div>'}</section>`;}
function render(){const route=location.hash.slice(1)||'inicio';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));$('#live-count').textContent=data.matches.filter(m=>m.status==='live').length;$('#app').innerHTML=route==='inicio'?home():route==='partidos'?matches():route==='tabla'?heading('Tabla de posiciones','Cada punto nos acerca a la copa.')+table():route==='equipos'?teamsView():route==='estadisticas'?stats():route==='panel'?panel():route==='reglamento'?heading('Reglamento','Propuesta de bases · pendiente de validación de la organización')+`<div class="panel rule"><h3>01 / Formato de competencia</h3><p>Liga todos contra todos. Los cuatro primeros clasifican a playoffs. Estas bases son una propuesta inicial y deben ser confirmadas por la organización.</p><h3>02 / Puntaje y desempates</h3><p>Victoria: 3 puntos. Empate: 1 punto. Derrota: 0 puntos. El orden se define por puntos, diferencia de gol y goles a favor. Si persiste la igualdad, la organización resolverá el desempate; mientras tanto se muestran por nombre.</p><h3>03 / Planteles y alineaciones</h3><p>Cada capitán gestiona únicamente su equipo. Las alineaciones se componen de hasta 11 titulares y se bloquean cuando el partido está en juego o finalizado.</p><h3>04 / Resultados oficiales</h3><p>Solo la administración registra marcadores, estado del partido y eventos. La tabla incluye únicamente partidos finalizados.</p></div>`:heading('Página no encontrada','Vuelve a la vista general para seguir la liga.');}
function show(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function showTeam(id){const t=team(id);show(`${crest(t)}<h2>${esc(t.name)}</h2><span class="eyebrow">PLANTEL OFICIAL</span>${data.players.filter(p=>p.team_id===id).map(p=>`<div class="roster-row"><span><b class="green">${p.number}</b> ${esc(p.name)}</span><span class="tag">${p.position}</span></div>`).join('')||'<div class="empty">Plantel pendiente de inscripción.</div>'}`);}
function showMatch(id,side){const m=data.matches.find(m=>m.id===id);if(!m)return;side=side||m.home_id;const lineup=data.lineups.find(l=>l.match_id===id&&l.team_id===side);const list=(lineup?.player_ids||[]).map(player).filter(Boolean);show(`<span class="eyebrow">JORNADA ${m.round} · ${date(m.kickoff)}</span>${matchCard(m)}<h3>Minuto a minuto</h3><ul class="events">${data.events.filter(e=>e.match_id===id).sort((a,b)=>a.minute-b.minute).map(e=>`<li><b class="green">${e.minute}′</b> ${e.type==='goal'?'⚽ Gol':e.type==='yellow'?'🟨 Tarjeta amarilla':'🟥 Tarjeta roja'} · ${esc(player(e.player_id)?.name||team(e.team_id).name)}</li>`).join('')||'<li>Aún no hay eventos registrados.</li>'}</ul><h3>Alineaciones</h3><div class="filters">${[m.home_id,m.away_id].map(t=>`<button class="${side===t?'selected':''}" data-lineup-side="${t}" data-match-id="${id}">${esc(team(t).name)}</button>`).join('')}</div>${lineup?`<p class="muted">Formación ${esc(lineup.formation)}</p><div class="pitch">${['POR','DEF','MED','DEL'].map(pos=>`<div class="pitch-line">${list.filter(p=>p.position===pos).map(p=>`<div class="pitch-player"><span class="shirt">${p.number}</span>${esc(p.name)}</div>`).join('')}</div>`).join('')}</div>`:'<div class="empty">El capitán todavía no ha publicado su alineación.</div>'}`);}
async function refresh(){const version=++loadVersion;const tables=['teams','players','matches','events','lineups'];const results=await Promise.all(tables.map(t=>db.from(t).select('*')));const error=results.find(r=>r.error)?.error;if(error)throw error;if(version!==loadVersion)return;data=Object.fromEntries(tables.map((t,i)=>[t,results[i].data]));render();}
async function save(table,row,id){if(demo){if(id){const index=data[table].findIndex(x=>x.id===id);if(index<0)throw Error('Registro no encontrado');data[table][index]={...data[table][index],...row};}else data[table].push({id:uid(),...row});localStorage.setItem('benjaix-demo-v1',JSON.stringify(data));}else{const result=id?await db.from(table).update(row).eq('id',id).select():await db.from(table).insert(row).select();if(result.error)throw result.error;if(!result.data?.length)throw Error('No tienes permiso para realizar este cambio.');await refresh();}toast('Cambios guardados');}
function scoreEditor(id){const m=data.matches.find(m=>m.id===id);if(!m){$('#score-editor').innerHTML='';return;}$('#score-editor').innerHTML=`<form id="score-form" data-id="${id}" class="form-grid" style="margin-top:20px"><div class="admin-grid"><label>${esc(team(m.home_id).name)}<input name="home_score" type="number" min="0" max="99" value="${m.home_score}" required></label><label>${esc(team(m.away_id).name)}<input name="away_score" type="number" min="0" max="99" value="${m.away_score}" required></label></div><label>Estado<select name="status">${Object.entries(statusText).map(([v,l])=>`<option value="${v}" ${v===m.status?'selected':''}>${l}</option>`).join('')}</select></label><label>Minuto<input name="minute" type="number" min="0" max="150" value="${m.minute}" required></label><button>Actualizar marcador</button></form><h3 style="margin-top:25px">Registrar evento</h3><p class="muted">Los eventos alimentan las estadísticas. Ajusta el marcador por separado para confirmar el resultado oficial.</p><form id="event-form" data-id="${id}" class="form-grid"><label>Jugador<select name="player_id" required><option value="">Selecciona jugador</option>${data.players.filter(p=>[m.home_id,m.away_id].includes(p.team_id)).map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(team(p.team_id).name)}</option>`).join('')}</select></label><label>Tipo<select name="type"><option value="goal">Gol</option><option value="yellow">Tarjeta amarilla</option><option value="red">Tarjeta roja</option></select></label><label>Minuto<input name="minute" type="number" min="0" max="150" required value="${m.minute}"></label><button>Guardar evento</button></form>${data.events.filter(e=>e.match_id===id).map(e=>`<div class="roster-row"><span>${e.minute}′ · ${esc(e.type)} · ${esc(player(e.player_id)?.name||'Jugador')}</span><button data-delete-event="${e.id}">Eliminar evento</button></div>`).join('')}`;}
function lineupEditor(id){const m=data.matches.find(m=>m.id===id),target=$('#lineup-editor');if(!m){target.innerHTML='';return;}if(m.status!=='scheduled'){target.innerHTML='<p class="notice">La alineación está bloqueada porque el partido ya comenzó.</p>';return;}const l=data.lineups.find(l=>l.match_id===id&&l.team_id===selectedTeam);target.innerHTML=`<form id="lineup-form" data-id="${id}" class="form-grid" style="margin-top:20px"><label>Formación<select name="formation">${['4-3-3','4-4-2','3-5-2','4-2-3-1'].map(f=>`<option ${l?.formation===f?'selected':''}>${f}</option>`).join('')}</select></label><p class="muted">Selecciona hasta 11 titulares. Se dibujan según su posición registrada.</p>${data.players.filter(p=>p.team_id===selectedTeam).map(p=>`<label style="display:flex;align-items:center"><input name="player_ids" type="checkbox" value="${p.id}" ${l?.player_ids.includes(p.id)?'checked':''}>${p.number} · ${esc(p.name)} (${p.position})</label>`).join('')}<button>Publicar alineación</button></form>`;}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-filter],[data-match],[data-team],[data-demo],[data-lineup-side],[data-delete-player],[data-delete-event],#logout,.close');if(!t)return;try{if(t.matches('.close'))return $('#modal').close();if(t.dataset.lineupSide)return showMatch(t.dataset.matchId,t.dataset.lineupSide);if(t.dataset.filter){filter=t.dataset.filter;return render();}if(t.dataset.team){e.preventDefault();return showTeam(t.dataset.team);}if(t.dataset.match){if(!$('#modal').open)showMatch(t.dataset.match);return;}if(t.dataset.demo){demoProfile={id:t.dataset.demo==='admin'?'demo-admin':'demo-captain',role:t.dataset.demo};if(t.dataset.demo==='captain'&&data.teams[0])data.teams[0].captain_id='demo-captain';render();}if(t.id==='logout'){if(!demo){const {error}=await db.auth.signOut();if(error)throw error;}profile=null;demoProfile=null;render();}const key=t.dataset.deletePlayer?'players':t.dataset.deleteEvent?'events':null;if(key){if(!confirm('¿Confirmas que quieres eliminar este registro?'))return;const id=t.dataset.deletePlayer||t.dataset.deleteEvent;if(demo){if(key==='players'&&(data.events.some(x=>x.player_id===id)||data.lineups.some(x=>x.player_ids.includes(id))))throw Error('Este jugador tiene eventos o alineaciones. Retíralo de las alineaciones antes de eliminarlo; los jugadores con eventos se conservan.');data[key]=data[key].filter(x=>x.id!==id);localStorage.setItem('benjaix-demo-v1',JSON.stringify(data));}else{const {data:deleted,error}=await db.from(key).delete().eq('id',id).select();if(error)throw error;if(!deleted.length)throw Error('No se pudo eliminar: revisa tus permisos.');await refresh();}render();toast('Registro eliminado');}}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('article[role="button"]'))e.target.click();});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#match-list').innerHTML=filteredMatches();}});
document.addEventListener('change',e=>{if(e.target.id==='owned-team'){selectedTeam=e.target.value;render();}if(e.target.id==='manage-match')scoreEditor(e.target.value);if(e.target.id==='lineup-match')lineupEditor(e.target.value);});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f),v=Object.fromEntries(fd),button=f.querySelector('button');button.disabled=true;try{if(f.id==='login'){if(!db)throw Error('Supabase no está conectado.');const {data:auth,error}=await db.auth.signInWithPassword(v);if(error)throw error;const result=await db.from('profiles').select('*').eq('id',auth.user.id).single();if(result.error)throw Error('Tu cuenta aún no tiene un rol asignado por la organización.');profile=result.data;render();return;}if(f.id==='team-form')await save('teams',{...v,short_name:v.short_name.toUpperCase(),captain_id:null});if(f.id==='edit-team'){if('captain_id'in v){v.captain_id=v.captain_id.trim()||null;if(v.captain_id&&!/^[0-9a-f-]{36}$/i.test(v.captain_id))throw Error('El UUID del capitán no es válido.');}await save('teams',v,selectedTeam);}if(f.id==='player-form'){v.number=Number(v.number);if(data.players.some(p=>p.team_id===selectedTeam&&p.number===v.number))throw Error('Ese dorsal ya está ocupado.');await save('players',{...v,team_id:selectedTeam});}if(f.id==='match-form'){if(v.home_id===v.away_id)throw Error('Selecciona dos equipos diferentes.');await save('matches',{...v,kickoff:new Date(v.kickoff).toISOString(),round:Number(v.round),home_score:0,away_score:0,minute:0,status:'scheduled'});}if(f.id==='score-form'){await save('matches',{...v,home_score:Number(v.home_score),away_score:Number(v.away_score),minute:Number(v.minute)},f.dataset.id);}if(f.id==='event-form'){await save('events',{...v,match_id:f.dataset.id,team_id:player(v.player_id).team_id,minute:Number(v.minute)});}if(f.id==='lineup-form'){const ids=fd.getAll('player_ids');if(ids.length<1||ids.length>11)throw Error('Selecciona entre 1 y 11 titulares.');const old=data.lineups.find(l=>l.match_id===f.dataset.id&&l.team_id===selectedTeam);await save('lineups',{match_id:f.dataset.id,team_id:selectedTeam,formation:v.formation,player_ids:ids},old?.id);}render();}catch(err){toast(err.message);}finally{button.disabled=false;}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
async function init(){render();const c=window.BENJAIX_CONFIG;if(!c?.supabaseUrl||!c?.supabaseKey)return;$('#connection').textContent='Conectando…';try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.49.1');db=createClient(c.supabaseUrl,c.supabaseKey);const {data:auth}=await db.auth.getSession();if(auth.session){const result=await db.from('profiles').select('*').eq('id',auth.session.user.id).single();profile=result.data;}demo=false;data={teams:[],players:[],matches:[],events:[],lineups:[]};await refresh();$('#connection').textContent='Conectado a Supabase';db.channel('benjaix-public').on('postgres_changes',{event:'*',schema:'public'},()=>{refresh().catch(()=>toast('No se pudieron sincronizar los cambios.'));if($('#modal').open)$('#modal').close();}).subscribe(status=>{$('#connection').textContent=status==='SUBSCRIBED'?'● Datos en tiempo real':status==='CHANNEL_ERROR'||status==='TIMED_OUT'?'Conectado · tiempo real sin conexión':'Conectando tiempo real…';});db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){profile=null;render();}if(event==='TOKEN_REFRESHED'&&!session){profile=null;render();}});}catch(err){demo=true;db=null;profile=null;data=structuredClone(initial);$('#connection').textContent='Demo · Supabase pendiente';render();toast('No se pudo cargar la base de datos. Mostrando datos de demostración.');console.warn('Supabase:',err.message);}}
init();
